#!/usr/bin/env python3
"""gen_decoders.py <out.h>: straight-line record decoders, one per shape signature (1-4 columns, each NULL, INTEGER or
TEXT), and a table the plan picks from by signature. Each decoder is qc_decode_fast unrolled for that shape: every
column's type byte is checked against its class in sequence, values are written for all columns (no mask), and the
first mismatch returns 0 so the caller takes the generic decoder. Generated at build time (the Makefile's build/gen); not committed."""
import itertools, sys

CLS = {'N': 1, 'I': 2, 'T': 3}   # K_NUL, K_INT, K_TXT in qc.c

def col(c, k):
    if c == 'N':
        return [f'  if (*h++ != 0) return 0;', f'  cols[{k}].type = SQLITE_NULL;']
    if c == 'I':
        return [f'  {{ u32 t = *h++; if (t == 0 || t == 7 || t > 9) return 0;',
                f'    cols[{k}].type = SQLITE_INTEGER; cols[{k}].i = qc_int(t, d); d += qc_iw[t]; }}']
    return [f'  {{ u32 t = *h++; if (t >= 0x80) {{ if (h >= he || (*h & 0x80)) return 0; t = ((t & 0x7f) << 7) | *h++; }}',
            f'    if (t < 13 || !(t & 1)) return 0;',
            f'    u32 len = (t - 13) >> 1; cols[{k}].type = SQLITE_TEXT; cols[{k}].z = d; cols[{k}].n = (int)len; d += len; }}']

def main(out):
    L = ['/* generated by qc/gen_decoders.py: one straight-line decoder per record shape; do not edit */']
    table = {}
    for n in range(1, 5):
        for sig in itertools.product('NIT', repeat=n):
            name = 'qc_dec_' + ''.join(sig)
            code = sum(CLS[c] << (2 * k) for k, c in enumerate(sig)) | (n << 8)
            table[code] = name
            # each text column may take 2 header bytes: the header holds at most n + #T bytes after its size byte
            L.append(f'static int {name}(const u8 *rec, u32 sz, QcVal *cols) {{')
            L.append('  u32 hl = rec[0]; if (hl >= 0x80 || hl > sz) return 0;')
            L.append('  const u8 *h = rec + 1, *he = rec + hl, *d = rec + hl;')
            for k, c in enumerate(sig):
                L.append('  if (h >= he) return 0;')
                L += col(c, k)
            L.append('  return h < he ? d <= rec + sz : d == rec + sz;')   # (qc_decode_fast's end check)
            L.append('}')
    L.append('typedef int (*qc_dec_fn)(const u8 *, u32, QcVal *);')
    # dispatch by signature code: a jump table into the inlined decoders (no call through a pointer)
    L.append('static inline int qc_dec_run(u32 code, const u8 *rec, u32 sz, QcVal *cols) {')
    L.append('  switch (code) {')
    for code, name in sorted(table.items()): L.append(f'    case {code}: return {name}(rec, sz, cols);')
    L.append('  }')
    L.append('  return 0;')
    L.append('}')
    L.append('static u32 qc_dec_code(const QcShape *sh) {')
    L.append('  if (!sh->ok || sh->n < 1 || sh->n > 4) return 0;')
    L.append('  u32 code = (u32)sh->n << 8; for (int k = 0; k < sh->n; k++) { if (sh->cls[k] > 3) return 0; code |= (u32)sh->cls[k] << (2 * k); }   /* (K_REAL: none generated) */')
    L.append('  return code;')
    L.append('}')
    L.append('static qc_dec_fn qc_dec_pick(const QcShape *sh) {')
    L.append('  if (!sh->ok || sh->n < 1 || sh->n > 4) return 0;')
    L.append('  u32 code = (u32)sh->n << 8; for (int k = 0; k < sh->n; k++) { if (sh->cls[k] > 3) return 0; code |= (u32)sh->cls[k] << (2 * k); }   /* (K_REAL: none generated) */')
    L.append('  switch (code) {')
    for code, name in sorted(table.items()):
        L.append(f'    case {code}: return {name};')
    L.append('  }')
    L.append('  return 0;')
    L.append('}')
    open(out, 'w').write('\n'.join(L) + '\n')

if __name__ == '__main__':
    main(sys.argv[1])
